import{c as a,Q as s,j as n,m as e}from"./chunks/framework.DOi4mjdC.js";const c=JSON.parse('{"title":"InitBufPool","description":"","frontmatter":{},"headers":[{"level":1,"title":"InitBufPool","slug":"initbufpool"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TBufPool/InitBufPool-55.md","filePath":"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TBufPool/InitBufPool-55.md"}'),l={name:"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TBufPool/InitBufPool-55.md"};function o(p,t,i,d,u,r){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="initbufpool" tabindex="-1">InitBufPool <a class="header-anchor" href="#initbufpool" aria-label="Permalink to &quot;InitBufPool&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>√</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>通过Tpipe::InitBufPool接口可划分出整块资源，整块TbufPool资源可以继续通过TBufPool::InitBufPool接口划分成小块资源。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>非共享模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;class T&gt;</span></span>
<span class="line"><span>__aicore__ inline bool InitBufPool(T&amp; bufPool, uint32_t len)</span></span></code></pre></div></li><li><p>共享模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;class T, class U&gt;</span></span>
<span class="line"><span>__aicore__ inline bool InitBufPool(T&amp; bufPool, uint32_t len, U&amp; shareBuf)</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>说明</th></tr></thead><tbody><tr><td>T</td><td>bufPool参数的类型。</td></tr><tr><td>U</td><td>shareBuf参数的类型。</td></tr></tbody></table><p><strong>表 2</strong> InitBufPool(T&amp; bufPool, uint32_t len) 原型定义参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>bufPool</td><td>输入</td><td>新划分的资源池，类型为TBufPool。</td></tr><tr><td>len</td><td>输入</td><td>新划分资源池长度，单位为字节，非32字节对齐会自动向上补齐至32字节对齐。</td></tr></tbody></table><p><strong>表 3</strong> InitBufPool(T&amp; bufPool, uint32_t len, U&amp; shareBuf) 原型定义参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>bufPool</td><td>输入</td><td>新划分的资源池，类型为TBufPool。</td></tr><tr><td>len</td><td>输入</td><td>新划分资源池长度，单位为字节，非32字节对齐会自动向上补齐至32字节对齐。</td></tr><tr><td>shareBuf</td><td>输入</td><td>被复用资源池，类型为TBufPool，新划分资源池与被复用资源池共享起始地址及长度。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ol><li>新划分的资源池与被复用资源池的物理内存需要一致，两者共享起始地址及长度；</li><li>输入长度需要小于等于被复用资源池长度；</li><li>其他泛用约束参考<a href="./TBufPool.html">TBufPool</a>；</li></ol><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>数据量较大且内存有限时，无法一次完成所有数据搬运，需要拆分成多个阶段计算，每次计算使用其中的一部分数据，可以通过TBufPool资源池进行内存地址复用。本例中，从Tpipe划分出资源池tbufPool0，tbufPool0为src0Gm分配空间后，继续分配了资源池tbufPool1，指定tbufPool1与tbufPool2复用并分别运用于第一、二轮计算，此时tbufPool1及tbufPool2共享起始地址及长度。</p><p>完整样例链接可以参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/04_resource_management/tbufpool_management" target="_blank" rel="noreferrer">tbufpool_management样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::TPipe* pipe;</span></span>
<span class="line"><span>AscendC::TBufPool&lt;AscendC::TPosition::VECCALC&gt; tbufPool0, tbufPool1, tbufPool2;</span></span>
<span class="line"><span>// srcQue0、srcQue1、srcQue2为VECIN上的TQue，dstQue0、dstQue1为VECOUT上的TQue</span></span>
<span class="line"><span>// 从Tpipe划分出资源池tbufPool0</span></span>
<span class="line"><span>pipe-&gt;InitBufPool(tbufPool0, bufSize * 4);</span></span>
<span class="line"><span>// 通过tbufPool0给tbufPool1分配空间，并指定tbufPool1与tbufPool2复用同一块空间</span></span>
<span class="line"><span>tbufPool0.InitBufPool(tbufPool1, bufSize * 2);</span></span>
<span class="line"><span>// 给srcQue0分配空间</span></span>
<span class="line"><span>tbufPool0.InitBuffer(srcQue0, 1, bufSize * 2); // Total src0</span></span>
<span class="line"><span>tbufPool0.InitBufPool(tbufPool2, bufSize * 2, tbufPool1);</span></span>
<span class="line"><span>// 通过tbufPool1给srcQue1、dstQue0分配空间</span></span>
<span class="line"><span>tbufPool1.InitBuffer(srcQue1, 1, bufSize);</span></span>
<span class="line"><span>tbufPool1.InitBuffer(dstQue0, 1, bufSize);</span></span>
<span class="line"><span>CopyIn();</span></span>
<span class="line"><span>Compute();</span></span>
<span class="line"><span>CopyOut();</span></span>
<span class="line"><span>// 切换资源池到tbufPool2，并通过tbufPool2给srcQue2、dstQue1分配空间</span></span>
<span class="line"><span>tbufPool1.Reset();</span></span>
<span class="line"><span>tbufPool2.InitBuffer(srcQue2, 1, bufSize);</span></span>
<span class="line"><span>tbufPool2.InitBuffer(dstQue1, 1, bufSize);</span></span>
<span class="line"><span>CopyIn1();</span></span>
<span class="line"><span>Compute1();</span></span>
<span class="line"><span>CopyOut1();</span></span>
<span class="line"><span>tbufPool2.Reset();</span></span>
<span class="line"><span>tbufPool0.Reset();</span></span>
<span class="line"><span>pipe-&gt;Reset();</span></span></code></pre></div>`,22)])])}const b=a(l,[["render",o]]);export{c as __pageData,b as default};
